import { roles, statuses, tenants, store, rulesFor, canSubmit, canApprove } from './model.js';

// UI question: compare workspace, overview-first and legal-focus layouts via ?variant=A|B|C.
const icons = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  folder: '<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  users: '<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v2"/>',
  shield: '<path d="m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7Z"/><path d="m8 12 3 3 5-6"/>',
  settings: '<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',
  send: '<path d="m22 2-7 20-4-9-9-4Z"/><path d="m11 13 11-11"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  arrow: '<path d="M5 12h14m-5-5 5 5-5 5"/>',
  down: '<path d="m6 9 6 6 6-6"/>',
  file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8m-8 4h5"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  warning: '<path d="m12 3 10 18H2Z"/><path d="M12 9v4m0 4h.01"/>',
  upload: '<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-12 9a3 3 0 0 0 6 0"/>',
  building: '<path d="M5 22V3h14v19M2 22h20M9 7h1m4 0h1m-6 4h1m4 0h1m-6 4h1m4 0h1m-4 7v-4h2v4"/>',
  logout: '<path d="M9 4H4v16h5m6-12 4 4-4 4m-6-4h10"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
  download: '<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  help: '<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 1-1 1-1 2m0 3h.01"/>'
};
const ico = (name, cls = '') => `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.file}</svg>`;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const initials = name => name.split(' ').slice(-2).map(x => x[0]).join('');
const params = new URLSearchParams(location.search);
const state = { tenant: 'anphat', role: 'admin', page: 'dashboard', variant: ['A','B','C'].includes(params.get('variant')) ? params.get('variant') : 'A', search: '', filter: '', selected: null, tab: 'overview', doc: null, mobile: false };
if (state.variant === 'C') state.page = 'legal';
const db = () => store[state.tenant];
const tenant = () => tenants.find(t => t.id === state.tenant);
const current = () => db().dossiers.find(d => d.id === state.selected);
const editable = () => ['admin','intake','legal'].includes(state.role);
const scoped = () => state.role === 'platform' ? [] : db().dossiers.filter(d => state.role !== 'legal' || d.assignee === 2);
const menus = [['dashboard','grid','Tổng quan'],['dossiers','folder','Hồ sơ'],['legal','shield','Kiểm tra pháp lý'],['employees','users','Nhân viên'],['handoff','send','Bàn giao'],['settings','settings','Cấu hình']];
const allowed = page => state.role === 'platform' ? page === 'platform' : !['employees','settings'].includes(page) || state.role === 'admin';
const badge = status => `<span class="badge ${status}"><i></i>${esc(statuses[status] || ({ active:'Đang hoạt động', invited:'Đã mời', suspended:'Tạm ngưng', confirmed:'Đã xác nhận', review:'Cần xác nhận', replaced:'Đã thay thế', unclassified:'Chờ phân loại', sent:'Thành công', failed:'Thất bại', none:'Chưa gửi' }[status] || status))}</span>`;
const avatar = (name, i = 0) => `<span class="avatar tone-${i % 4}">${esc(initials(name))}</span>`;
const employee = id => db().employees.find(e => e.id === id);
const count = status => scoped().filter(d => d.status === status).length;
const userName = () => state.role === 'legal' ? 'Trần Hoàng Nam' : state.role === 'intake' ? 'Lê Thảo Nguyên' : state.role === 'viewer' ? 'Đặng Đức Anh' : 'Nguyễn Minh Anh';
function nav() {
  return (state.role === 'platform' ? [['platform','building','Doanh nghiệp']] : menus.filter(m => allowed(m[0]))).map(([key, icon, label]) => `<button data-page="${key}" class="nav-item ${state.page === key || state.page === 'detail' && key === 'dossiers' ? 'active' : ''}">${ico(icon)}<span>${label}</span>${key === 'legal' && count('legal') ? `<small>${count('legal')}</small>` : ''}${key === 'dossiers' ? '<span class="nav-dot"></span>' : ''}</button>`).join('');
}
function render() {
  const labels = { dashboard:'Tổng quan', dossiers:'Quản lý hồ sơ', employees:'Quản lý nhân viên', legal:'Kiểm tra pháp lý', settings:'Cấu hình doanh nghiệp', handoff:'Bàn giao hồ sơ', detail:'Chi tiết hồ sơ', platform:'Quản trị nền tảng' };
  document.documentElement.dataset.variant = state.variant;
  document.querySelector('#app').innerHTML = `
    <a href="#main-content" class="skip-link">Đến nội dung chính</a>
    <aside class="sidebar ${state.mobile ? 'open' : ''}">
      <a class="brand" href="/">${ico('folder')}<span>folio<span class="brand-dot">.</span></span></a>
      <div class="workspace-label">KHÔNG GIAN LÀM VIỆC</div>
      <label class="tenant-picker"><span class="tenant-logo">${tenant().initials}</span><select id="tenant-select" aria-label="Chọn doanh nghiệp" ${state.role === 'platform' ? 'disabled' : ''}>${tenants.filter(t => t.active || t.id === state.tenant).map(t => `<option value="${t.id}" ${t.id === state.tenant ? 'selected' : ''}>${t.name}</option>`).join('')}</select>${ico('down')}</label>
      <div class="nav-label">QUẢN LÝ</div><nav aria-label="Điều hướng chính">${nav()}</nav>
      <div class="sidebar-bottom"><div class="workspace-health"><span class="health-dot"></span> Không gian thử nghiệm <span>↗</span></div><button class="nav-item" data-action="help">${ico('help')}<span>Hướng dẫn sử dụng</span></button><button class="user" data-action="login">${avatar(userName(), 1)}<span><strong>${userName()}</strong><small>${roles[state.role]}</small></span>${ico('logout')}</button></div>
    </aside>
    <div class="app-shell">
      <header class="topbar"><div class="breadcrumbs"><button class="mobile-toggle icon-button" data-action="mobile" aria-label="Mở menu">☰</button><span>${esc(tenant().name)}</span><span class="crumb-slash">/</span><strong>${labels[state.page]}</strong></div><div class="top-actions"><span class="demo-label"><i></i> Dữ liệu mô phỏng</span><button class="icon-button" data-action="notifications" aria-label="Thông báo">${ico('bell')}<i class="notification-dot"></i></button><span class="top-divider"></span>${avatar(userName(), 1)}</div></header>
      <div class="horizontal-nav"><span class="mini-brand">folio.</span>${nav()}<button class="button subtle" data-action="login">${ico('users')} ${esc(roles[state.role])}</button></div>
      <main id="main-content" tabindex="-1">${!allowed(state.page === 'detail' ? 'dossiers' : state.page) ? empty('shield','Bạn không có quyền truy cập','Chọn vai trò khác trong phiên đăng nhập mô phỏng.') : state.page === 'dashboard' ? dashboard() : state.page === 'dossiers' ? dossierList() : state.page === 'detail' ? detail() : state.page === 'employees' ? employees() : state.page === 'legal' ? legal() : state.page === 'settings' ? settings() : state.page === 'handoff' ? handoff() : platform()}</main>
      <footer class="page-footer"><span>Folio workspace <b>·</b> Prototype theo PRODUCT_PLAN.md</span><span>Toàn bộ OCR, đối soát và bàn giao đều mô phỏng.</span></footer>
    </div>
    <div class="prototype-switcher" aria-label="So sánh bố cục prototype"><button data-action="prev-variant" aria-label="Bố cục trước">←</button><div><span>PROTOTYPE</span><strong>${state.variant} · ${{A:'Workspace',B:'Command center',C:'Legal focus'}[state.variant]}</strong></div><button data-action="next-variant" aria-label="Bố cục tiếp theo">→</button><small>${roles[state.role]} · ${esc(tenant().initials)} · ${scoped().length} hồ sơ</small></div>`;
}
function heading(kicker, title, subtitle, actions = '') { return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`; }
function empty(icon, title, subtitle) { return `<div class="empty">${ico(icon)}<h3>${title}</h3><p>${subtitle}</p></div>`; }
function dashboard() {
  const all = scoped().length, approved = count('approved'), waiting = count('legal'), supplement = count('supplement');
  return `${heading('KHÔNG GIAN CỦA BẠN', 'Một ngày làm việc hiệu quả<span class="greeting-dot">.</span>', `Chào ${userName().split(' ').slice(-2).join(' ')}, đây là tình hình hồ sơ tại ${esc(tenant().name)}.`, `<span class="date-chip">${ico('clock')} 31 tháng 10, 2026</span>${editable() ? `<button class="button primary" data-action="create">${ico('plus')} Tạo hồ sơ</button>` : ''}`)}
    <div class="welcome-strip"><div class="welcome-icon">${ico('shield')}</div><div><strong>Mọi hồ sơ, một không gian.</strong><p>${waiting} hồ sơ đang chờ kiểm tra pháp lý. Cùng hoàn tất những việc quan trọng hôm nay.</p></div><button data-page="legal" class="text-link">Đến hàng đợi ${ico('arrow')}</button><div class="strip-decoration"></div></div>
    <section class="stats-grid" aria-label="Thống kê hồ sơ">
      ${[[all,'Tổng hồ sơ','folder','Tất cả hồ sơ doanh nghiệp','neutral'],[waiting,'Chờ kiểm tra pháp lý','shield','Sẵn sàng để chuyên viên kiểm tra','amber'],[supplement,'Cần bổ sung','clock','Cần liên hệ người cung cấp','orange'],[approved,'Đã phê duyệt','check',`${all ? Math.round(approved / all * 100) : 0}% tổng số hồ sơ`,'green']].map(([n,label,icon,sub,color],i)=>`<button class="stat-card" data-stat="${['','legal','supplement','approved'][i]}"><div><span>${label}</span><span class="stat-icon ${color}">${ico(icon)}</span></div><strong>${String(n).padStart(2,'0')}<span class="sparkline">${[18,28,22,38,30,45,36,54,42,61].map((h,j)=>`<i style="height:${h}%;opacity:${.25+j*.07}"></i>`).join('')}</span></strong><small><i class="${color}"></i>${sub}</small></button>`).join('')}
    </section>
    <div class="overview-grid"><section class="panel recent-panel"><div class="panel-heading"><div><h2>Hồ sơ gần đây <span class="count-label">${all}</span></h2><p>Theo dõi tiến độ và tiếp tục công việc của bạn</p></div><button class="text-link" data-page="dossiers">Xem tất cả ${ico('arrow')}</button></div>${table(scoped().slice(0,5), true)}</section>
    <aside class="panel tasks-panel"><div class="panel-heading"><div><h2>Cần bạn chú ý</h2><p>Ưu tiên công việc trong ngày</p></div><span class="task-number">${waiting + supplement}</span></div><div class="tasks">${scoped().filter(d=>['supplement','legal'].includes(d.status)).slice(0,3).map((d,i)=>`<button class="task" data-open="${d.id}"><span class="task-icon ${d.status === 'supplement' ? 'orange' : 'amber'}">${ico(d.status === 'supplement' ? 'warning' : 'shield')}</span><span><strong>${d.status === 'supplement' ? 'Bổ sung tài liệu' : 'Kiểm tra pháp lý'}</strong><small>${esc(d.name)}</small><span class="task-meta">${d.id} <b>·</b> ${i ? 'Hôm nay' : 'Ưu tiên'}</span></span><span class="task-arrow">↗</span></button>`).join('') || empty('check','Đã hoàn tất','Không có công việc cần chú ý.')}</div><div class="daily-note">${ico('file')}<p><strong>Một quy trình, rõ từng bước.</strong><br/>Mọi thay đổi đều được ghi vào lịch sử hồ sơ.</p></div></aside></div>
    <section class="panel pipeline-panel"><div class="panel-heading"><div><h2>Nhịp xử lý hồ sơ</h2><p>Phân bổ hồ sơ theo từng giai đoạn hiện tại</p></div><span class="muted">${all} hồ sơ trong không gian</span></div><div class="pipeline">${[['receiving','Tiếp nhận'],['processing','Xử lý tài liệu'],['legal','Kiểm tra pháp lý'],['approved','Phê duyệt']].map(([s,l],i)=>`<button data-stat="${s}" class="pipeline-step"><span class="step-top"><span class="step-index">0${i+1}</span><strong>${count(s)}</strong></span><div class="progress"><i style="width:${all ? count(s)/all*100 : 0}%"></i></div><span>${l}</span>${i<3 ? '<span class="step-arrow">→</span>' : ''}</button>`).join('')}</div></section>`;
}
function table(rows, compact = false) {
  return rows.length ? `<div class="table-wrap"><table><thead><tr><th>HỒ SƠ / KHÁCH HÀNG</th>${compact ? '' : '<th>LOẠI HỒ SƠ</th>'}<th>TRẠNG THÁI</th><th>PHỤ TRÁCH</th><th>NGÀY TẠO</th><th><span class="sr-only">Mở</span></th></tr></thead><tbody>${rows.map((d,i)=>`<tr><td><button class="record-link" data-open="${d.id}"><span class="file-icon">${ico('file')}</span><span><strong>${esc(d.name)}</strong><small>${d.id}</small></span></button></td>${compact ? '' : `<td><span class="type-name">${d.type}</span></td>`}<td>${badge(d.status)}</td><td><span class="assignee">${avatar(employee(d.assignee)?.name || 'Chưa phân công',i)}<span>${esc((employee(d.assignee)?.name || 'Chưa phân công').split(' ').slice(-2).join(' '))}</span></span></td><td class="date-cell">${d.date}</td><td><button class="icon-button" data-open="${d.id}" aria-label="Mở ${d.id}">${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('folder','Chưa có hồ sơ phù hợp','Thử đổi bộ lọc hoặc tạo một hồ sơ mới.');
}
function dossierList() {
  const rows = scoped().filter(d => (!state.filter || d.status === state.filter) && (d.id + d.name + d.type).toLowerCase().includes(state.search.toLowerCase()));
  return `${heading('HỒ SƠ DOANH NGHIỆP','Mỗi hồ sơ, một hành trình.','Quản lý tài liệu, tiến độ và người phụ trách tại một nơi.',editable() ? `<button class="button primary" data-action="create">${ico('plus')} Tạo hồ sơ</button>` : '')}<section class="panel"><div class="list-tabs">${[['','Tất cả'],['receiving','Tiếp nhận'],['processing','Đang xử lý'],['legal','Chờ pháp lý'],['supplement','Cần bổ sung'],['approved','Đã duyệt']].map(([s,l])=>`<button class="${state.filter === s ? 'selected' : ''}" data-filter="${s}">${l}<span>${s ? count(s) : scoped().length}</span></button>`).join('')}</div><div class="toolbar"><label class="search-box">${ico('search')}<input id="search" placeholder="Tìm theo mã, khách hàng, loại hồ sơ…" value="${esc(state.search)}" aria-label="Tìm hồ sơ" /></label><span class="muted">${rows.length} hồ sơ</span><button class="button" data-action="reset-filter">Xóa bộ lọc</button></div><div id="table-results">${table(rows)}</div></section>`;
}
function detail() {
  const d = current();
  if (!d || !scoped().includes(d)) return empty('shield','Không thể truy cập hồ sơ','Hồ sơ không thuộc doanh nghiệp hoặc phạm vi hiện tại.');
  const rules = rulesFor(d);
  return `<button class="back-link" data-page="dossiers">← Danh sách hồ sơ</button>${heading(d.id,esc(d.name),`${esc(d.address)} <span class="dot-separator">·</span> ${d.type}`,`${badge(d.status)}${d.status !== 'approved' && editable() ? `<button class="button" data-action="upload">${ico('upload')} Thêm tài liệu</button>` : ''}`)}
    <div class="detail-meta"><span>${ico('users')} ${esc(employee(d.assignee)?.name || 'Chưa phân công')}${state.role === 'admin' ? '<button class="text-link" data-action="assign">Thay đổi</button>' : ''}</span><span>${ico('settings')} Cấu hình ${d.config}</span><span>${ico('file')} Lượt xử lý ${d.version}</span></div>
    <div class="detail-tabs">${[['overview','Tổng quan'],['documents','Tài liệu'],['compare','Đối soát'],['history','Lịch sử']].map(([key,label])=>`<button class="${state.tab === key ? 'selected' : ''}" data-tab="${key}">${label}${key === 'documents' ? `<span>${d.documents.length}</span>` : ''}</button>`).join('')}</div>
    ${d.status === 'approved' ? `<div class="notice success">${ico('shield')} Hồ sơ đã được phê duyệt. Nội dung lượt xử lý này được giữ nguyên.${editable() ? '<button class="text-link" data-action="reopen">Mở lượt xử lý mới →</button>' : ''}</div>` : ''}
    ${state.tab === 'overview' ? `<div class="detail-grid"><section class="panel"><div class="panel-heading"><div><h2>Danh mục giấy tờ</h2><p>Đầy đủ tài liệu trước khi chuyển kiểm tra pháp lý</p></div><span class="count-label">${d.documents.filter(x=>x.status === 'confirmed').length}/3 xác nhận</span></div>${['Căn cước công dân','Giấy chứng nhận','Hợp đồng'].map(type=>{const doc=d.documents.find(x=>x.type===type&&x.status!=='replaced');return `<button class="checklist-row" ${doc ? `data-doc="${doc.id}"` : 'data-action="upload"'}><span class="checklist-icon ${doc?.status==='confirmed'?'green':''}">${ico(doc?.status==='confirmed'?'check':'file')}</span><span><strong>${type}</strong><small>${doc ? esc(doc.name) : 'Chưa tiếp nhận tài liệu'}</small></span>${doc ? badge(doc.status) : '<span class="badge supplement"><i></i>Còn thiếu</span>'}<span>→</span></button>`;}).join('')}<div class="panel-bottom">${ico('help')} Danh mục minh họa theo cấu hình ${d.config} của doanh nghiệp.</div></section><aside class="panel"><div class="panel-heading"><div><h2>Bước tiếp theo</h2><p>Luồng xử lý của hồ sơ</p></div></div><div class="next-step"><span class="large-icon">${ico('shield')}</span><h3>${d.status==='legal'?'Sẵn sàng kiểm tra pháp lý':d.status==='approved'?'Bàn giao kết quả':'Hoàn thiện tài liệu'}</h3><p>${canSubmit(d)?'Tài liệu đã xác nhận, các quy tắc đã được đánh giá.':'Bổ sung đủ tài liệu và xác nhận dữ liệu trích xuất để tiếp tục.'}</p>${d.status === 'approved' ? '<button class="button primary" data-page="handoff">Đến bàn giao →</button>' : d.status === 'legal' ? `<button class="button primary" data-tab="compare">Kiểm tra đối soát →</button>` : `<button class="button primary" data-action="submit" ${!canSubmit(d)||!editable()?'disabled':''}>Chuyển kiểm tra pháp lý →</button>`}</div></aside></div><section class="panel batches"><div class="panel-heading"><div><h2>Các đợt tiếp nhận</h2><p>Tài liệu bổ sung được ghi nhận cùng hồ sơ</p></div></div>${d.batches.map(b=>`<div class="batch-row"><span class="file-icon">${ico('upload')}</span><strong>Đợt ${String(b.id).padStart(2,'0')}</strong><span>${esc(b.sender)}</span><span>${b.count} tài liệu</span><small>${esc(b.date)}</small></div>`).join('')}</section>` : state.tab === 'documents' ? documents(d) : state.tab === 'compare' ? `<section class="panel"><div class="panel-heading"><div><h2>Kết quả đối soát</h2><p>So sánh giá trị giữa các nguồn tài liệu đã xác nhận · Mô phỏng</p></div>${d.status!=='approved'&&editable()?'<button class="button" data-action="rerun">Chạy đối soát</button>':''}</div>${rules.map(r=>`<div class="rule-row"><div><strong>${r.name}</strong><small>${r.sources}</small></div><div class="rule-values"><span>${esc(r.left || 'Chưa có dữ liệu')}</span><span>↔</span><span>${esc(r.right || 'Chưa có dữ liệu')}</span></div><span class="badge ${r.status==='match'?'confirmed':r.status==='waiting'?'receiving':'supplement'}"><i></i>${{match:'Khớp',waiting:'Chờ dữ liệu',mismatch:'Sai lệch'}[r.status]}</span></div>`).join('')}<div class="resolution"><label for="resolution">Ý kiến pháp lý / cách xử lý sai lệch</label><textarea id="resolution" placeholder="Ghi rõ căn cứ xử lý trước khi phê duyệt…" ${d.status==='approved'||state.role!=='legal'?'disabled':''}>${esc(d.resolution)}</textarea><div class="resolution-actions">${state.role==='legal'&&d.status!=='approved'?'<button class="button" data-action="save-resolution">Lưu ý kiến</button><button class="button" data-action="supplement">Yêu cầu bổ sung</button>':''}<button class="button primary" data-action="approve" ${!canApprove(d,state.role)?'disabled':''}>${ico('shield')} Phê duyệt hồ sơ</button></div><small class="muted">Chỉ chuyên viên pháp lý được phân công được duyệt khi đủ dữ liệu và đã xử lý sai lệch.</small></div></section>` : `<section class="panel"><div class="panel-heading"><div><h2>Lịch sử xử lý</h2><p>Mỗi thao tác đều gắn với người thực hiện và lượt xử lý</p></div></div><div class="timeline">${d.history.toReversed().map(h=>`<div><span class="timeline-dot"></span><strong>${esc(h.text)}</strong><p>${esc(h.by)} <b>·</b> ${esc(h.time)}</p></div>`).join('')}</div>${d.snapshots.length ? `<div class="panel-bottom">${d.snapshots.length} lượt đã duyệt được giữ nguyên. <button class="text-link" data-action="snapshot">Tải bản duyệt gần nhất</button></div>`:''}</section>`}`;
}
function documents(d) {
  const active = d.documents.find(x=>x.id===state.doc) || d.documents.find(x=>x.status!=='replaced');
  return `<section class="review-layout"><aside class="panel document-list"><div class="panel-heading"><h2>Tài liệu <span class="count-label">${d.documents.length}</span></h2></div>${d.documents.map(doc=>`<button class="document-item ${active?.id===doc.id?'selected':''}" data-doc="${doc.id}">${ico('file')}<span><strong>${esc(doc.name)}</strong><small>Đợt ${doc.batch} · ${doc.type}</small>${badge(doc.status)}</span></button>`).join('')}</aside>${active ? `<div class="document-preview"><div class="preview-toolbar">${ico('file')} ${esc(active.name)}<span>1 / 1</span></div><div class="paper"><div class="paper-watermark">MÔ PHỎNG</div><div class="paper-emblem">✧</div><h4>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</h4><small>Độc lập – Tự do – Hạnh phúc</small><hr/><h3>${esc(active.type.toLocaleUpperCase('vi'))}</h3><p class="document-disclaimer">BẢN MINH HỌA GIAO DIỆN<br/>Không phải tài liệu gốc hoặc kết quả OCR</p><div class="paper-fields"><p>Họ và tên: <strong>${esc(active.subject || 'Chưa xác định')}</strong></p><p>Số hiệu: <strong>${esc(active.number || '—')}</strong></p><p>Địa chỉ: ${esc(d.address)}</p>${active.area?`<p>Diện tích: <strong>${esc(active.area)} m²</strong></p>`:''}</div><div class="paper-signature">Tài liệu mô phỏng<br/><span>Folio demo</span></div></div></div><section class="panel extraction"><div class="panel-heading"><div><h2>Dữ liệu trích xuất</h2><p>Giá trị mẫu · không chạy OCR thực tế</p></div></div><form id="extract-form" class="form-body"><label>Loại giấy tờ<select name="type" ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}>${['Chưa phân loại','Căn cước công dân','Giấy chứng nhận','Hợp đồng'].map(t=>`<option ${t===active.type?'selected':''}>${t}</option>`).join('')}</select></label><label>Họ tên chủ sở hữu<input name="subject" value="${esc(active.subject)}" required ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}/></label><label>Số hiệu / số định danh<input name="number" value="${esc(active.number)}" ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}/></label><label>Diện tích (m²)<input name="area" value="${esc(active.area)}" ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}/></label><label>Lý do điều chỉnh<textarea name="reason" placeholder="Bắt buộc khi sửa dữ liệu đã trích xuất" ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}></textarea></label><div class="notice">${ico('help')} Xác nhận phân loại sẽ mô phỏng trích xuất lại. Dữ liệu thay đổi được đối soát lại.</div><button class="button primary full" type="submit" ${d.status==='approved'||!editable()||active.status==='replaced'?'disabled':''}>${ico('check')} Xác nhận dữ liệu</button>${d.status!=='approved'&&editable()&&active.status!=='replaced'?'<button class="button full" type="button" data-action="replace-doc">Thay thế tài liệu</button>':''}</form></section>` : empty('file','Chưa có tài liệu','Thêm tài liệu để bắt đầu.')}</section>`;
}
function employees() {
  return `${heading('ĐỘI NGŨ CỦA BẠN','Đúng người, đúng công việc.','Quản lý thành viên và vai trò trong doanh nghiệp.',`<button class="button primary" data-action="invite">${ico('plus')} Mời thành viên</button>`)}<section class="panel"><div class="panel-heading"><div><h2>Thành viên <span class="count-label">${db().employees.length}</span></h2><p>Quyền truy cập độc lập trong từng doanh nghiệp</p></div></div><div class="table-wrap"><table><thead><tr><th>THÀNH VIÊN</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th><th>HỒ SƠ PHỤ TRÁCH</th><th>THAO TÁC</th></tr></thead><tbody>${db().employees.map((e,i)=>`<tr><td><span class="assignee">${avatar(e.name,i)}<span><strong>${esc(e.name)}</strong><small>${esc(e.email)}</small></span></span></td><td>${roles[e.role]}</td><td>${badge(e.status)}</td><td>${db().dossiers.filter(d=>d.assignee===e.id).length} hồ sơ</td><td><button class="button small" data-edit-employee="${e.id}">${e.status==='invited'?'Quản lý lời mời':'Chỉnh sửa'}</button></td></tr>`).join('')}</tbody></table></div></section><div class="notice">${ico('shield')} Vai trò quản trị doanh nghiệp không tự động có quyền phê duyệt pháp lý.</div>`;
}
function legal() {
  const rows = scoped().filter(d=>d.status === 'legal');
  return `${heading('HÀNG ĐỢI PHÁP LÝ','Kiểm tra kỹ. Quyết định rõ.','Xem tài liệu, đối chiếu dữ liệu và ghi nhận quyết định phê duyệt.',`<span class="date-chip">${ico('shield')} ${rows.length} hồ sơ đang chờ</span>`)}${state.role !== 'legal' ? `<div class="notice">${ico('help')} Bạn đang xem với vai trò ${roles[state.role]}. <button class="text-link" data-action="login">Chuyển sang chuyên viên pháp lý để thử phê duyệt →</button></div>`:''}<div class="legal-grid">${rows.map(d=>`<article class="panel legal-card"><div class="legal-card-top"><span class="file-icon">${ico('folder')}</span>${badge(d.status)}</div><small>${d.id}</small><h2>${esc(d.name)}</h2><p>${esc(d.address)}</p><div class="legal-readiness"><span>${ico('check')} Đủ 3 loại giấy tờ</span><span>${ico('check')} ${rulesFor(d).filter(r=>r.status==='match').length}/2 quy tắc khớp</span></div><div class="legal-card-bottom"><span class="assignee">${avatar(employee(d.assignee)?.name||'Chưa phân công',1)} ${esc((employee(d.assignee)?.name||'Chưa phân công').split(' ').slice(-2).join(' '))}</span><button class="button primary" data-review="${d.id}">Kiểm tra ${ico('arrow')}</button></div></article>`).join('') || empty('shield','Hàng đợi đã trống','Không có hồ sơ chờ kiểm tra trong phạm vi được giao.')}</div>`;
}
function settings() {
  return `${heading('CẤU HÌNH DOANH NGHIỆP','Quy trình của doanh nghiệp bạn.','Phiên bản mới chỉ áp dụng cho hồ sơ tạo sau khi phát hành.',`<button class="button primary" data-action="${db().draft?'publish':'draft'}">${ico('plus')} ${db().draft?'Phát hành v1.3':'Tạo bản nháp mới'}</button>`)}<div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2>Loại bộ hồ sơ</h2><p>Danh mục giấy tờ và quy tắc đối soát</p></div><span class="badge confirmed"><i></i>${db().config} · Đã phát hành</span></div>${['Chuyển nhượng nhà đất','Chuyển nhượng căn hộ'].map(t=>`<div class="config-row"><span class="file-icon">${ico('folder')}</span><div><h3>${t}</h3><p>3 loại giấy tờ bắt buộc · 2 quy tắc đối soát</p></div><span class="badge confirmed"><i></i>Đang sử dụng</span></div>`).join('')}<div class="panel-bottom">CCCD · Giấy chứng nhận · Hợp đồng<br/>Họ tên chủ sở hữu và diện tích được so sánh bằng nhau giữa hai nguồn.</div></section><aside class="panel"><div class="panel-heading"><h2>Quản lý phiên bản</h2></div><div class="form-body"><div class="version-item"><span class="version-dot"></span><div><strong>${db().config}</strong><p>Đã phát hành · cấu hình hiện tại</p></div></div>${db().draft?'<div class="version-item"><span class="version-dot draft"></span><div><strong>v1.3</strong><p>Bản nháp · chưa áp dụng</p></div></div>':''}<div class="notice">${ico('help')} Hồ sơ hiện có giữ nguyên cấu hình đã gắn khi tạo.</div></div></aside></div>${db().draft?'<div class="notice">Bản nháp v1.3 đang sao chép cấu hình hiện tại để minh họa vòng đời phát hành. Trình chỉnh sửa trường và quy tắc chưa nằm trong prototype.</div>':''}`;
}
function handoff() {
  const rows = scoped().filter(d=>d.status==='approved');
  return `${heading('SAU PHÊ DUYỆT','Sẵn sàng cho bước tiếp theo.','Xuất kết quả và theo dõi bàn giao độc lập với quyết định phê duyệt.')}<div class="notice">${ico('help')} Bàn giao chỉ được mô phỏng trong bộ nhớ; xuất JSON tải bản dữ liệu mẫu xuống thiết bị.</div><section class="panel"><div class="panel-heading"><h2>Hồ sơ đã duyệt <span class="count-label">${rows.length}</span></h2></div>${rows.map(d=>`<div class="handoff-row"><span class="file-icon">${ico('send')}</span><div><strong>${esc(d.name)}</strong><small>${d.id} · ${d.attempts} lần gửi</small></div>${badge(d.handoff)}<span class="badge approved"><i></i>Đã phê duyệt</span><button class="button" data-export="${d.id}">${ico('download')} Xuất JSON</button>${editable() ? `<button class="button ${d.handoff==='failed'?'primary':''}" data-send="${d.id}" ${d.handoff==='sent'?'disabled':''}>${d.handoff==='failed'?'Thử gửi lại':d.handoff==='sent'?'Đã bàn giao':'Gửi mô phỏng'}</button>` : ''}</div>`).join('')||empty('send','Chưa có hồ sơ đã duyệt','Hoàn thành kiểm tra pháp lý trước khi bàn giao.')}</section>`;
}
function platform() {
  return `${heading('QUẢN TRỊ NỀN TẢNG','Không gian doanh nghiệp.','Quản lý vòng đời doanh nghiệp. Vai trò này không có quyền đọc hồ sơ.')}<section class="panel">${tenants.map(t=>`<div class="config-row"><span class="tenant-logo">${t.initials}</span><div><h3>${esc(t.name)}</h3><p>Quản trị: admin@${t.id}.vn</p></div>${badge(t.active?'active':'suspended')}<button class="button" data-toggle-tenant="${t.id}">${t.active?'Tạm ngưng':'Kích hoạt'}</button></div>`).join('')}</section>`;
}
function toast(message) { const el=document.querySelector('#toast'); el.textContent=message; el.classList.add('visible'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('visible'),4000); }
let modalReturnFocus;
function closeModal() { document.querySelector('#modal-root').innerHTML=''; document.body.classList.remove('modal-open'); modalReturnFocus?.focus(); }
function modal(title, subtitle, body, submitLabel, onSubmit) {
  modalReturnFocus=document.activeElement;
  document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-modal" aria-label="Đóng">${ico('close')}</button></div><form id="modal-form"><div class="form-body">${body}</div><div class="modal-footer"><button class="button" type="button" data-action="close-modal">Hủy</button><button class="button primary" type="submit">${submitLabel}</button></div></form></section></div>`;
  document.body.classList.add('modal-open');
  document.querySelector('#modal-form').onsubmit=event=>{event.preventDefault();onSubmit(new FormData(event.target));};
  document.querySelector('.modal input, .modal select, .modal textarea, .modal button')?.focus();
}
function log(d,text) { d.history.push({text,by:userName(),time:new Date().toLocaleString('vi-VN')}); }
function download(data, filename) { const a=document.createElement('a'); const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})); a.href=url; a.download=filename; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
function switchVariant(delta) { const keys=['A','B','C']; state.variant=keys[(keys.indexOf(state.variant)+delta+3)%3]; const url=new URL(location.href);url.searchParams.set('variant',state.variant);history.replaceState(null,'',url); if(state.role!=='platform')state.page=state.variant==='C'?'legal':'dashboard'; state.selected=null; render(); }
function navigate(page) { state.page=page;state.search='';state.filter='';state.mobile=false;render();window.scrollTo(0,0); }
function openDossier(id,review=false) { const d=scoped().find(d=>d.id===id);if(!d)return toast('Hồ sơ không nằm trong phạm vi truy cập.');state.selected=id;state.page='detail';state.tab=review?'compare':'overview';state.doc=null;render();window.scrollTo(0,0); }
const actions = {
  'close-modal':closeModal,
  'next-variant':()=>switchVariant(1), 'prev-variant':()=>switchVariant(-1),
  mobile:()=>{state.mobile=!state.mobile;render();},
  help:()=>modal('Khám phá Folio','Prototype dựa trên PRODUCT_PLAN.md', '<ol class="help-list"><li>Tạo hồ sơ trong doanh nghiệp đang chọn.</li><li>Thêm tài liệu theo từng đợt, xác nhận phân loại và dữ liệu.</li><li>Xem đối soát, chuyển sang kiểm tra pháp lý.</li><li>Chuyển vai trò sang chuyên viên pháp lý để ghi ý kiến và duyệt hồ sơ được giao.</li><li>Xuất JSON và thử bàn giao mô phỏng.</li></ol><div class="notice">Dữ liệu chỉ tồn tại trong bộ nhớ; tải lại trang sẽ đặt lại bản mẫu. Dùng ← → để so sánh 3 bố cục.</div>','Đã hiểu',closeModal),
  notifications:()=>modal('Công việc cần chú ý','Thông báo trong doanh nghiệp hiện tại',`<p>${count('legal')} hồ sơ chờ pháp lý.</p><p>${count('supplement')} hồ sơ cần bổ sung.</p>`,'Đến hàng đợi',()=>{closeModal();navigate('legal');}),
  login:()=>modal('Đăng nhập mô phỏng','Chọn vai trò để trải nghiệm phạm vi truy cập.',`<label>Vai trò<select name="role">${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${v===state.role?'selected':''}>${l}</option>`).join('')}</select></label><div class="notice">Đây là phiên giả lập, không phải xác thực hoặc kiểm soát quyền trên backend. Chuyên viên mẫu chỉ được duyệt hồ sơ giao cho Trần Hoàng Nam.</div>`,'Vào không gian',data=>{state.role=data.get('role');if(!tenant().active&&state.role!=='platform'){const active=tenants.find(t=>t.active);if(!active)return toast('Không có doanh nghiệp đang hoạt động.');state.tenant=active.id;}state.page=state.role==='platform'?'platform':state.role==='legal'?'legal':'dashboard';state.selected=null;closeModal();render();}),
  create:()=>{if(!editable())return;modal('Tạo hồ sơ mới',`Không gian ${tenant().name} · Cấu hình ${db().config}`,`<label>Họ tên khách hàng<input name="name" placeholder="Ví dụ: Nguyễn Văn An" required maxlength="80"/></label><label>Mã tham chiếu<input name="reference" placeholder="Để trống để tạo tự động" maxlength="40"/></label><label>Loại hồ sơ<select name="type"><option>Chuyển nhượng nhà đất</option><option>Chuyển nhượng căn hộ</option></select></label><label>Địa chỉ giao dịch<input name="address" placeholder="Địa chỉ bất động sản" required maxlength="160"/></label><label>Chuyên viên phụ trách<select name="assignee">${db().employees.filter(e=>e.status==='active'&&e.role==='legal').map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label>`,'Tạo hồ sơ',data=>{const id=String(data.get('reference')||`${tenant().initials}-2026-${Date.now().toString().slice(-6)}`).trim();if(db().dossiers.some(d=>d.id===id))return toast('Mã tham chiếu đã tồn tại.');const d={id,name:data.get('name').trim(),type:data.get('type'),address:data.get('address').trim(),assignee:Number(data.get('assignee')),status:'receiving',date:'31/10/2026',version:1,config:db().config,documents:[],history:[],batches:[],snapshots:[],resolution:'',handoff:'none',attempts:0};if(!d.name||!d.address||!employee(d.assignee))return toast('Vui lòng nhập đủ thông tin và chọn người phụ trách.');db().dossiers.unshift(d);log(d,'Tạo hồ sơ, áp dụng cấu hình '+d.config);closeModal();openDossier(id);toast('Đã tạo hồ sơ mới.');});},
  upload:()=>uploadModal(), 'replace-doc':()=>uploadModal(true),
  submit:()=>{const d=current();if(!d||!editable()||!canSubmit(d)||d.status==='approved')return;d.status='legal';log(d,'Chuyển kiểm tra pháp lý');render();toast('Đã chuyển hồ sơ sang hàng đợi pháp lý.');},
  rerun:()=>{const d=current();if(!d||!editable()||d.status==='approved')return;log(d,'Chạy lại đối soát mô phỏng theo dữ liệu hiện tại');render();toast('Đã đánh giá lại các quy tắc mô phỏng.');},
  'save-resolution':()=>{const d=current();if(!d||state.role!=='legal'||d.status==='approved')return;d.resolution=document.querySelector('#resolution').value.trim();log(d,'Lưu ý kiến kiểm tra pháp lý');render();toast('Đã lưu ý kiến.');},
  supplement:()=>{const d=current();if(!d||state.role!=='legal'||d.status==='approved')return;modal('Yêu cầu bổ sung',d.id,'<label>Nội dung cần bổ sung<textarea name="reason" required placeholder="Mô tả tài liệu hoặc thông tin còn thiếu…"></textarea></label>','Gửi yêu cầu',data=>{const reason=data.get('reason').trim();if(!reason)return;d.status='supplement';log(d,'Yêu cầu bổ sung: '+reason);closeModal();render();toast('Đã ghi nhận yêu cầu bổ sung.');});},
  approve:()=>{const d=current();if(!d||!canApprove(d,state.role))return;modal('Xác nhận phê duyệt',`${d.id} · ${d.name}`,`<p>Quyết định sẽ lưu chuyên viên thực hiện, thời gian, ý kiến và nội dung lượt xử lý ${d.version}.</p><label>Ý kiến phê duyệt<textarea name="comment" required placeholder="Nhập kết luận kiểm tra…"></textarea></label><div class="notice">Quyết định và kết quả trong prototype đều là mô phỏng.</div>`,'Xác nhận phê duyệt',data=>{if(!canApprove(d,state.role))return;const comment=data.get('comment').trim();if(!comment)return;d.status='approved';log(d,'Phê duyệt lượt '+d.version+': '+comment);d.snapshots.push(JSON.parse(JSON.stringify({...d,snapshots:[]})));closeModal();render();toast('Đã phê duyệt mô phỏng và lưu bản nội dung đã duyệt.');});},
  reopen:()=>{const d=current();if(!d||!editable()||d.status!=='approved')return;modal('Mở lượt xử lý mới',d.id,'<p>Bản nội dung đã duyệt được giữ nguyên. Mọi cập nhật trong lượt mới phải kiểm tra và phê duyệt lại.</p>','Mở lượt mới',()=>{d.version++;d.status='processing';d.resolution='';d.handoff='none';d.attempts=0;log(d,'Mở lượt xử lý mới '+d.version);closeModal();render();});},
  snapshot:()=>{const d=current();if(d?.snapshots.length)download({simulated:true,...d.snapshots.at(-1)},d.id+'-approved.json');},
  assign:()=>{const d=current();if(!d||state.role!=='admin')return;modal('Phân công hồ sơ',d.id,`<label>Chuyên viên phụ trách<select name="assignee">${db().employees.filter(e=>e.role==='legal'&&e.status==='active').map(e=>`<option value="${e.id}" ${d.assignee===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>`,'Lưu phân công',data=>{d.assignee=Number(data.get('assignee'));log(d,'Phân công cho '+employee(d.assignee)?.name);closeModal();render();});},
  invite:()=>{if(state.role!=='admin')return;modal('Mời thành viên','Lời mời chỉ được tạo trong bộ nhớ, không gửi email.',`<label>Họ tên<input name="name" required maxlength="80"/></label><label>Email<input name="email" type="email" required/></label><label>Vai trò<select name="role">${Object.entries(roles).filter(([r])=>r!=='platform').map(([r,l])=>`<option value="${r}">${l}</option>`).join('')}</select></label>`,'Tạo lời mời',data=>{if(db().employees.some(e=>e.email.toLowerCase()===data.get('email').toLowerCase()))return toast('Email này đã có trong danh sách thành viên.');db().employees.push({id:Date.now(),name:data.get('name').trim(),email:data.get('email'),role:data.get('role'),status:'invited'});closeModal();render();toast('Đã tạo lời mời mô phỏng, chưa gửi email.');});},
  draft:()=>{if(state.role!=='admin')return;db().draft=true;render();toast('Đã tạo bản nháp cấu hình v1.3.');},
  publish:()=>{if(state.role!=='admin')return;modal('Phát hành cấu hình v1.3','Hồ sơ đang xử lý giữ nguyên phiên bản đã gắn.','<p>Phiên bản mới được chọn mặc định cho các hồ sơ tạo sau thời điểm phát hành.</p>','Phát hành',()=>{db().config='v1.3';db().draft=false;closeModal();render();});},
  'reset-filter':()=>{state.filter='';state.search='';render();}
};
function uploadModal(replace=false) {
  const d=current();if(!d||!editable()||d.status==='approved')return;
  const previous=replace?d.documents.find(x=>x.id===state.doc):null;if(replace&&!previous)return;
  modal(replace?'Thay thế tài liệu':'Thêm đợt tiếp nhận',`${d.id} · Không tải nội dung tệp lên máy chủ`, `<label>Người cung cấp<input name="sender" value="${esc(d.name)}" required/></label><label>Chọn tệp minh họa<input name="files" type="file" ${replace?'':'multiple'} accept=".pdf,.png,.jpg,.jpeg" required/></label><label>Loại giấy tờ<select name="type">${['Chưa phân loại','Căn cước công dân','Giấy chứng nhận','Hợp đồng'].map(t=>`<option ${t===previous?.type?'selected':''}>${t}</option>`).join('')}</select></label><div class="notice">Chỉ tên tệp được dùng trong demo. Khung xem trước và dữ liệu trích xuất là minh họa; không đọc nội dung tệp thật.</div>`,replace?'Thay tài liệu':'Thêm tài liệu',data=>{
    const files=data.getAll('files').filter(f=>f.size);if(!files.length)return toast('Vui lòng chọn tệp không rỗng.');const batch=d.batches.length+1;
    if(previous)previous.status='replaced';
    files.forEach((file,i)=>d.documents.push({id:Date.now()+i,name:file.name,type:data.get('type'),status:data.get('type')==='Chưa phân loại'?'unclassified':'review',subject:d.name,number:'DEMO-'+(100+i),area:data.get('type')==='Căn cước công dân'?'':'86,5',batch}));
    d.batches.push({id:batch,sender:data.get('sender'),count:files.length,date:new Date().toLocaleString('vi-VN')});d.status='processing';d.resolution='';log(d,`${replace?'Thay thế tài liệu':'Tiếp nhận đợt '+batch}: ${files.map(f=>f.name).join(', ')}; đối soát liên quan chờ xác nhận lại`);closeModal();state.tab='documents';state.doc=d.documents.at(-1).id;render();toast('Đã ghi nhận tài liệu mô phỏng; cần xác nhận dữ liệu.');
  });
}
function editEmployee(id) {
  if(state.role!=='admin')return;const e=employee(id);if(!e)return;
  modal('Cập nhật thành viên',e.name,`<label>Vai trò<select name="role">${Object.entries(roles).filter(([r])=>r!=='platform').map(([r,l])=>`<option value="${r}" ${e.role===r?'selected':''}>${l}</option>`).join('')}</select></label><label>Trạng thái<select name="status">${(e.status==='invited'?[['invited','Đã mời'],['revoked','Thu hồi lời mời']]:[['active','Đang hoạt động'],['suspended','Tạm ngưng'],['left','Đã rời công ty']]).map(([v,l])=>`<option value="${v}" ${v===e.status?'selected':''}>${l}</option>`).join('')}</select></label><label>Chuyển hồ sơ sang (khi thu hồi quyền)<select name="transfer"><option value="">Chọn người thay thế</option>${db().employees.filter(x=>x.id!==id&&x.status==='active'&&x.role==='legal').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><div class="notice">Lưu thay đổi sẽ xác nhận cập nhật quyền trong phiên mô phỏng. Không thể vô hiệu hóa quản trị viên cuối cùng.</div>`,'Xác nhận thay đổi',data=>{
    const nextRole=data.get('role'),nextStatus=data.get('status');
    if(e.role==='admin'&&e.status==='active'&&(nextRole!=='admin'||nextStatus!=='active')&&db().employees.filter(x=>x.role==='admin'&&x.status==='active').length===1)return toast('Cần một quản trị viên hoạt động khác trước khi thay đổi.');
    const assigned=db().dossiers.filter(d=>d.assignee===id);
    if(assigned.length&&(nextStatus!=='active'||nextRole!=='legal')){const target=employee(Number(data.get('transfer')));if(!target)return toast('Chọn người nhận chuyển giao hồ sơ trước khi thu hồi quyền.');assigned.forEach(d=>{d.assignee=target.id;log(d,'Chuyển giao từ '+e.name+' sang '+target.name);});}
    e.role=nextRole;e.status=nextStatus;if(nextStatus==='revoked')db().employees=db().employees.filter(x=>x.id!==id);closeModal();render();toast('Đã cập nhật thành viên mô phỏng.');
  });
}
document.addEventListener('click',event=>{
  const el=event.target.closest('button');if(!el||el.disabled)return;
  if(el.dataset.action)return actions[el.dataset.action]?.();
  if(el.dataset.page)return navigate(el.dataset.page);
  if(el.dataset.open)return openDossier(el.dataset.open);
  if(el.dataset.review)return openDossier(el.dataset.review,true);
  if(el.dataset.tab){state.tab=el.dataset.tab;render();return;}
  if(el.dataset.doc){state.doc=Number(el.dataset.doc);state.tab='documents';render();return;}
  if(el.hasAttribute('data-stat')){state.page='dossiers';state.filter=el.dataset.stat;state.search='';render();return;}
  if(el.hasAttribute('data-filter')){state.filter=el.dataset.filter;render();return;}
  if(el.dataset.editEmployee)return editEmployee(Number(el.dataset.editEmployee));
  if(el.dataset.export){const d=scoped().find(d=>d.id===el.dataset.export);if(d?.status==='approved')download({simulated:true,tenant:tenant().name,...d},d.id+'.json');return;}
  if(el.dataset.send){const d=scoped().find(d=>d.id===el.dataset.send);if(!d||!editable()||d.status!=='approved')return;d.attempts++;d.handoff='sent';log(d,'Bàn giao mô phỏng thành công, lần '+d.attempts);render();toast('Bàn giao mô phỏng thành công. Không gửi tới hệ thống thật.');return;}
  if(el.dataset.toggleTenant&&state.role==='platform'){const t=tenants.find(t=>t.id===el.dataset.toggleTenant);modal(t.active?'Tạm ngưng doanh nghiệp?':'Kích hoạt doanh nghiệp?',t.name,'<p>Thay đổi trạng thái không gian trong phiên mô phỏng hiện tại.</p>','Xác nhận',()=>{t.active=!t.active;closeModal();render();});}
});
document.addEventListener('change',event=>{if(event.target.id==='tenant-select'){state.tenant=event.target.value;state.selected=null;state.page=state.role==='legal'?'legal':'dashboard';state.search='';state.filter='';render();toast('Đã chuyển sang '+tenant().name);}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.search=event.target.value;const rows=scoped().filter(d=>(!state.filter||d.status===state.filter)&&(d.id+d.name+d.type).toLowerCase().includes(state.search.toLowerCase()));document.querySelector('#table-results').innerHTML=table(rows);document.querySelector('.toolbar > .muted').textContent=rows.length+' hồ sơ';}});
document.addEventListener('submit',event=>{
  if(event.target.id!=='extract-form')return;event.preventDefault();const d=current();const doc=d?.documents.find(x=>x.id===state.doc)||d?.documents.find(x=>x.status!=='replaced');if(!d||!doc||!editable()||d.status==='approved'||doc.status==='replaced')return;
  const data=new FormData(event.target);if(data.get('type')==='Chưa phân loại')return toast('Chọn loại giấy tờ trước khi xác nhận.');
  const changed=['type','subject','number','area'].some(k=>String(doc[k]||'')!==String(data.get(k)||'').trim());
  if(changed&&!String(data.get('reason')).trim())return toast('Nhập lý do khi điều chỉnh dữ liệu.');
  for(const key of ['type','subject','number','area'])doc[key]=String(data.get(key)||'').trim();doc.status='confirmed';d.resolution='';if(d.status==='legal')d.status='processing';log(d,'Xác nhận dữ liệu '+doc.name+(changed?' · Lý do: '+data.get('reason'):''));render();toast('Đã xác nhận dữ liệu và cập nhật đối soát mô phỏng.');
});
document.addEventListener('keydown',event=>{
  const modalEl=document.querySelector('.modal');
  if(modalEl){if(event.key==='Escape')closeModal();if(event.key==='Tab'){const list=[...modalEl.querySelectorAll('button,input,select,textarea')].filter(e=>!e.disabled);const first=list[0],last=list.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}
  if(event.target.closest('input,textarea,select,[contenteditable]'))return;
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();switchVariant(event.key==='ArrowLeft'?-1:1);}
});
window.addEventListener('popstate',()=>{const variant=new URLSearchParams(location.search).get('variant');state.variant=['A','B','C'].includes(variant)?variant:'A';render();});
render();
